UPDATE TB_MSNGR_CHTRM
SET CHTRM_NM = #{vo.chtrmNm},
    CHTRM_EXPLN = #{vo.chtrmExpln}
WHERE CHTRM_ID = #{chtrmId}
AND END_DT IS NULL

UPDATE TB_MSNGR_CHTRM_PTCPT
SET LEAV_DT = SYSDATE
WHERE CHTRM_ID = #{chtrmId}
AND EMP_ID = #{empId}
AND LEAV_DT IS NULL

UPDATE TB_MSNGR_CHTRM_PTCPT
SET PTCPT_STTUS_CD = #{ptcptSttusCd}
WHERE EMP_ID = #{empId}

UPDATE TB_MSNGR_CHTRM_PTCPT
SET LAST_CFMTN_MSG_ID = #{msgId}
WHERE CHTRM_ID = #{chtrmId}
  AND EMP_ID   = #{empId}

UPDATE TB_MSNGR_CHTRM_PTCPT
SET LEAV_DT = SYSDATE
WHERE CHTRM_ID = #{chtrmId}
  AND EMP_ID = #{empId}
  AND LEAVE_DT IS NULL
